<?php if ($autoStart ?? false): ?><p class="status-banner status-pending" role="status">Opening secure Paystack checkout…</p><?php endif; ?>
<p>Choose your mobile money network on the secure Paystack page, then approve the payment in your mobile money app or phone prompt. We never ask for your mobile money PIN on this website.</p>
<?php if (str_starts_with(Paystack::config()['secret_key'], 'sk_test_')): ?><p><strong>Test checkout — no real money will be collected.</strong></p><?php endif; ?>
<?php if (Paystack::ready()): ?><form method="post" class="manage-form" <?= ($autoStart ?? false) ? 'data-auto-submit' : '' ?>><input type="hidden" name="csrf" value="<?= escape(Csrf::token()) ?>"><?php if (!$booking['customer_email']): ?><label class="field-label" for="payment-email">Email for your payment receipt</label><input id="payment-email" type="email" name="email" maxlength="190" autocomplete="email" required><?php endif; ?><button class="button" name="action" value="pay">Pay <?= money($booking['price']) ?> with Paystack</button></form><?php if ($autoStart ?? false): ?><script src="assets/js/payment.js" defer></script><?php endif; ?><?php else: ?><p>Online checkout is currently unavailable. You can still pay at the spa.</p><?php endif; ?>
<form method="post" class="manage-form"><input type="hidden" name="csrf" value="<?= escape(Csrf::token()) ?>"><button class="button" name="action" value="check">Check payment status</button></form>
<p>If money was deducted, check payment status before attempting another payment. Your appointment remains saved if payment is pending or checkout is closed.</p>
